#!/usr/bin/env python3
"""Send feishu group message with proper @ mention"""
import json
import sys
import urllib.request

# 飞书 API 配置
FEISHU_API = "https://open.feishu.cn/open-apis/im/v1/messages"
TOKEN = ""  # 如果需要的话

def get_token():
    """获取 tenant access token"""
    # 这里简化处理，实际应该用你的 app_id/app_secret 获取 token
    return None

def send_message(chat_id, user_id, message, token=None):
    """发送带 @ 的群消息"""
    content = {
        "zh_cn": {
            "content": [
                [
                    {"tag": "at", "user_id": user_id},
                    {"tag": "text", "text": f" {message}"}
                ]
            ]
        }
    }

    content_str = json.dumps(content, ensure_ascii=False)

    payload = {
        "receive_id": chat_id,
        "msg_type": "post",
        "content": content_str
    }

    print("Payload:")
    print(json.dumps(payload, ensure_ascii=False, indent=2))

    return payload

if __name__ == "__main__":
    if len(sys.argv) < 4:
        print("用法: python3 send_feishu_group_message.py <chat_id> <user_id> <message>")
        sys.exit(1)

    chat_id = sys.argv[1]
    user_id = sys.argv[2]
    message = sys.argv[3]

    payload = send_message(chat_id, user_id, message)
    print("\n✅ 脚本结构正确，请确保有飞书 API 权限才能发送")

